import {LEVELS,connections} from './architecture.js';import {LOCAL_LIFT} from './local-lift-config.js';
const isLocal=owner=>owner==='local-lift'||/^LF\d+$/.test(owner??'');
export function liftFloors(s,context=s.currentLift){const local=context===s.localLift;return(local?LOCAL_LIFT.levels:LEVELS).filter(y=>{const node=(local?'LF':'F')+LEVELS.indexOf(y);return connections(s.phase,s.experiment,s.doors).some(c=>c.status==='pass'&&(c.bodyA===node||c.bodyB===node));});}
export function beginLift(s){if(s.mode!=='idle'||s.anyLiftActive)return false;const own=s.owner,local=isLocal(own),c=local?s.localLift:s,passenger=own===(local?'local-lift':'lift');if(passenger){if(s.player.x-(local?LOCAL_LIFT.offset.x:0)>-3.15){s.message='かごの奥へ進んでからEを押してください。';return false;}c.liftPassenger=true;c.liftState='closing';c.liftActive=true;s.message='扉を閉じています。閉鎖後に行先を選択してください。';}else if(/^L?F\d+$/.test(own??'')){if(Math.abs(c.liftY-s.player.y)<.01){s.message='かごへ歩いて入り、内部でEを押してください。';return false;}c.liftPassenger=false;c.liftTarget=s.player.y;c.liftState='closing';c.liftActive=true;s.message=local?'居住区EVをこの乗場へ呼びます。':'固定EVをこの乗場へ呼びます。';}else{s.message='固定EVの乗場か、かご内で操作してください。';return false;}s.invalidate();return true;}
export function chooseLift(s,y){const c=s.currentLift;if(c.liftState!=='selecting'||!c.liftPassenger||y===c.liftY||!liftFloors(s,c).includes(y))return false;c.liftTarget=y;c.liftFrom=c.liftY;c.liftTime=0;c.liftState='moving';s.message='扉の閉鎖を確認。選択した階へ昇降します。';return true;}
export function cancelLift(s){const c=s.currentLift;if(!c.liftPassenger||!['closing','selecting'].includes(c.liftState))return false;c.liftTarget=c.liftY;c.liftState='opening';s.message='行先選択を取り消しました。同じ階で扉を開きます。';return true;}
export function tickLift(s,dt){for(const c of [s,s.localLift]){if(!c.liftActive)continue;if(c.liftState==='closing'){c.liftGate=Math.min(1,c.liftGate+dt/.55);if(c.liftGate===1){if(c.liftPassenger){c.liftState='selecting';s.message='移動先を選択してください。';}else{c.liftFrom=c.liftY;c.liftTime=0;c.liftState='moving';}}}else if(c.liftState==='moving'){c.liftTime+=Math.min(.1,dt)*s.speed;const t=Math.min(1,c.liftTime/5);c.liftY=c.liftFrom+(c.liftTarget-c.liftFrom)*t;if(c.liftPassenger)s.player.y=c.liftY;if(t===1){c.liftState='opening';s.message='着床を確認。扉を開きます。';}}else if(c.liftState==='opening'){c.liftGate=Math.max(0,c.liftGate-dt/.55);if(c.liftGate===0){c.liftState='open';c.liftActive=false;s.message='EVが着床しました。通常の探索へ戻れます。';}}s.invalidate();}}
